-- Add cards 601–630 to the existing rarity pools without changing pack odds.
on conflict (id) do nothing;

-- Extend the existing validated list while preserving the 450 JJ reward and all prior claims.
do $album$
declare
  current_api text := pg_get_functiondef('jj_collect.api(text,uuid,jsonb)'::regprocedure);
  updated_api text;
begin
  if strpos(current_api, '570,580,590,600,610,620,630)') > 0 then
    return;
  end if;

  updated_api := replace(current_api, '570,580,590,600)', '570,580,590,600,610,620,630)');
  if updated_api = current_api or strpos(current_api, 'bonus:=450;') = 0 then
    raise exception 'ALBUM_MILESTONE_RULE_NOT_FOUND';
  end if;
  execute updated_api;
end
$album$;
